#include <bits/stdc++.h>
using namespace std;

long long capacity(int c) {
    long long total = 0;
    for (long long left = 1, right; left <= c; left = right + 1) {
        long long q = c / left;
        right = c / q;
        total += q * (left + right) * (right - left + 1) / 2;
    }
    return total;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        int low = 1, high = n;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (capacity(mid) >= n) high = mid;
            else low = mid + 1;
        }
        int cost = low;
        vector<int> counts(cost + 1, 0);
        int remaining = n;
        for (int size = cost; size >= 1; --size) {
            counts[size] = min(cost / size, remaining / size);
            remaining -= counts[size] * size;
        }
        vector<int> assignment;
        assignment.reserve(n);
        int bag = 1;
        for (int size = 1; size <= cost; ++size) {
            for (int copy = 0; copy < counts[size]; ++copy) {
                for (int j = 0; j < size; ++j) assignment.push_back(bag);
                ++bag;
            }
        }
        cout << cost << '\n';
        for (int i = 0; i < n; ++i) cout << assignment[i] << (i + 1 == n ? '\n' : ' ');
    }
    return 0;
}

