            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
    }
    static long capacity(int c) {
        long total = 0;
        for (long left = 1, right; left <= c; left = right + 1) {
            long q = c / left;
            right = c / q;
            total += q * (left + right) * (right - left + 1) / 2;
        }
        return total;
    }
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int t = fs.nextInt();
        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            int n = fs.nextInt();
            int low = 1, high = n;
            while (low < high) {
                int mid = low + (high - low) / 2;
                if (capacity(mid) >= n) high = mid;
                else low = mid + 1;
            }
            int cost = low;
            int[] counts = new int[cost + 1];
            int remaining = n;
            for (int size = cost; size >= 1; --size) {
                counts[size] = Math.min(cost / size, remaining / size);
                remaining -= counts[size] * size;
