            int[] assignment = new int[n];
            int at = 0, bag = 1;
            for (int size = 1; size <= cost; ++size) {
                for (int copy = 0; copy < counts[size]; ++copy) {
                    for (int j = 0; j < size; ++j) assignment[at++] = bag;
                    ++bag;
                }
