        int t = fs.nextInt();
        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            int n = fs.nextInt(), k = fs.nextInt();
            int runs = n - k;
            if (runs == 1) {
                out.append(-1).append('\n');
                continue;
            }
            int zeroRuns = (runs + 1) / 2;
